const summaryInstant=value=>value===null||(typeof value==='string'&&value.length<=64&&Number.isFinite(Date.parse(value)));
function summaryQuery(filters){const q=new URLSearchParams({category:filters.category});for(const k of summaryDimensions)if(filters[k].length)q.set(k,filters[k].join(','));for(const k of ['minimum_edge','minimum_size'])if(filters[k]!==null)q.set(k,filters[k]);return q;}
